Method.Implementation:

 Do ##super(.pArray, item)
 set configValue=##class(Ens.Director).GetItemSettingValue(item.Name,"Host","DBtableName",.pstatus)
 if ($$$ISERR(pstatus))
 {
	 $$$LOGERROR("Can not read GetItemSettingValue: " _ DBtableName)
	 QUIT
 }

	SET tStatement = ##class(%SQL.Statement).%New()

	SET myquery=1
  	SET myquery(1)="select Target from " _ configValue	
  	SET qStatus = tStatement.%Prepare(.myquery)

    IF qStatus'=1 {
	    $$$LOGERROR(configName _ " SQL error in reading from " _ configValue _ ", shutting down.")  
	    QUIT 
	}
    SET rset = tStatement.%Execute()
    while (rset.%Next()) 
    {

	     if ("" '= $ZSTRIP(rset.Target, "*C"))
	     {
		   $$$TRACE("Target: " _ rset.Target)
	       Set pArray(rset.Target)=""
	     }
    }
